insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000930001','20000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000001100','multiple_choice','easy','published','Um compilador transforma um programa em C em código de máquina para uma ISA específica. Qual mudança pode ocorrer sem exigir que o código-fonte em C seja reescrito?') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
