insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000930001','Trocar a microarquitetura mantendo a mesma ISA.','A ISA é a interface visível ao software de baixo nível; a microarquitetura é uma implementação dessa interface.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
